package pe.ganadoconecta.modulos.reproduccion.aplicacion;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import pe.ganadoconecta.modulos.ganado.aplicacion.UnidadDeTrabajo;import pe.ganadoconecta.modulos.identidad.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.DatoReproductivoInvalidoException;
public final class CorregirParentesco{private final UnidadDeTrabajo u;private final AutorizarAccesoGanaderiaTransaccional auth;private final RepositorioGenealogia repo;private final Clock reloj;public CorregirParentesco(UnidadDeTrabajo u,AutorizarAccesoGanaderiaTransaccional a,RepositorioGenealogia r,Clock c){this.u=u;auth=a;repo=r;reloj=c;}public ResultadoParentesco ejecutar(SolicitudParentesco s,UUID actor,UUID sesion){if(s==null||s.operationId()==null||s.operationId().version()!=4)throw new DatoReproductivoInvalidoException("operationId");if(s.schemaVersion()!=1||s.tipo()==null)throw new DatoReproductivoInvalidoException("schemaVersion");Instant ahora=reloj.instant();byte[]h=huella(s,actor);return u.ejecutar(()->{auth.autorizar(actor,sesion,s.ganaderiaId(),PermisoGanaderia.ESCRIBIR,ahora);return repo.corregir(s,actor,h,ahora);});}private static byte[]huella(SolicitudParentesco s,UUID actor){try{return MessageDigest.getInstance("SHA-256").digest(String.join("\u001f",s.operationId().toString(),s.ganaderiaId().toString(),s.animalId().toString(),s.tipo().name(),Objects.toString(s.progenitorAnimalId(),""),actor.toString()).getBytes(StandardCharsets.UTF_8));}catch(NoSuchAlgorithmException x){throw new IllegalStateException(x);}}}
